package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TraceSampleRateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property trace sample rate of observed source ")
  void test_trace_sample_rate_v_o_builder() {
    Assertions.assertFalse(TraceSampleRateVO.nullValue().getTraceSampleRate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(TraceSampleRateVO.tryFrom(null).getTraceSampleRate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, TraceSampleRateVO.from(1).getTraceSampleRate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> TraceSampleRateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", TraceSampleRateVO.from(1).toString());
  }
}
